import datetime as dt, re
from pathlib import Path

def parse_events(path):
    t = Path(path).read_text(encoding="utf-8")
    evs = []
    for blk in re.findall(r"BEGIN:VEVENT(.*?)END:VEVENT", t, re.S):
        d = {}
        for line in blk.splitlines():
            if ":" in line:
                k, v = line.split(":", 1)
                d.setdefault(k.strip(), v.strip())
        evs.append((dt.datetime.strptime(d["DTSTART"], "%Y%m%dT%H%M%SZ"),
                    dt.datetime.strptime(d["DTEND"], "%Y%m%dT%H%M%SZ")))
    return evs

A = parse_events("/app/alice_calendar.ics")
B = parse_events("/app/bob_calendar.ics")
C = parse_events("/app/carol_calendar.ics")
busy = {e for e in A + B + C}
print("input event counts:", len(A), len(B), len(C))

out = Path("/app/meeting_scheduled.ics").read_text(encoding="utf-8")
assert out.startswith("BEGIN:VCALENDAR") and out.rstrip().endswith("END:VCALENDAR"), "envelope bad"
assert "VERSION:2.0" in out and "PRODID" in out, "headers bad"
for who in ("alice@example.com", "bob@example.com", "carol@example.com"):
    assert who in out, f"missing attendee {who}"
assert "Team Planning Meeting" in out, "summary missing"
start = dt.datetime.strptime(re.search(r"DTSTART:(\S+)", out).group(1), "%Y%m%dT%H%M%SZ")
end   = dt.datetime.strptime(re.search(r"DTEND:(\S+)", out).group(1), "%Y%m%dT%H%M%SZ")
print("scheduled:", start, "->", end, "dur(h):", (end-start).total_seconds()/3600)
assert end - start == dt.timedelta(hours=1)

def hm(t): return t.hour*60 + t.minute
LUNCH = (hm(dt.time(12,0)), hm(dt.time(12,30)))

def alice_ok(s, e):
    if s.weekday() > 4: return False
    return s.time() >= dt.time(9,0) and e.time() <= dt.time(14,0)

def bob_ok(s, e):
    if s.weekday() > 4: return False
    if s.time() < dt.time(10,0): return False
    if e.time() > dt.time(18,0): return False
    if s.weekday() in (1,3) and e.time() > dt.time(16,30): return False
    return True

def carol_ok(s, e):
    if s.weekday() > 4: return False
    if s.time() < dt.time(9,0) or e.time() > dt.time(17,0): return False
    # lunch overlap check
    if hm(s) < LUNCH[1] and hm(e) > LUNCH[0]: return False
    # 15-min buffer after any of her meetings ending >= 16:45
    for cs, ce in C:
        if ce.time() >= dt.time(16,45) and cs.date() == s.date():
            if s < ce + dt.timedelta(minutes=15) and e > cs: return False
    return True

def no_conflict(s, e):
    return not any(s < ce and e > cs for cs, ce in busy)

checks = {
    "alice": alice_ok(start, end), "bob": bob_ok(start, end), "carol": carol_ok(start, end),
    "no_conflict": no_conflict(start, end), "weekday": start.weekday() < 5,
}
print(checks)

# brute-force earliest at minute granularity
def valid(s, e):
    return alice_ok(s,e) and bob_ok(s,e) and carol_ok(s,e) and no_conflict(s,e)

day0 = dt.datetime(2024,1,15,0,0)
best = None
for d in range(5):
    cur = (day0 + dt.timedelta(days=d)).replace(hour=9)
    while cur.hour < 18:
        e = cur + dt.timedelta(hours=1)
        if valid(cur, e):
            best = (cur, e); break
        cur += dt.timedelta(minutes=1)
    if best: break
print("brute-force earliest:", best)
assert best and best[0] == start, "not earliest valid slot"
print("carol monday avoided:", start.weekday() != 0, "| alice morning:", start.time() < dt.time(12,0))
print("ALL CHECKS PASSED")
